-- 2026-10-17 (doc 247, step 3a): 2,795 owner-rights (SECURITY DEFINER) functions in public were executable by anon AND authenticated
-- (PUBLIC default). 746 of them are named nowhere in src/, supabase/functions/ or scripts/ and have no dependency that needs the
-- caller's EXECUTE right, so EXECUTE is revoked from PUBLIC/anon/authenticated and granted to service_role only.
-- Already applied to production 2026-10-17 in three batches; this file reproduces it. Idempotent: functions already closed are skipped.
-- SAFETY RULES (each function is KEPT, not revoked, if any applies):
--   (a) a policy, column default, constraint, trigger, index expression, security-invoker view or caller-run SQL-body function depends on it
--       (Postgres checks EXECUTE for the calling role in those places);
--   (b) its name appears in the body of a function that runs as the caller (SECURITY INVOKER);
--   (c) it has an explicit grant to a role other than postgres/anon/authenticated/service_role/supabase_admin (auth hooks, storage admin).
-- Every change is logged with the old ACL in _fn_lockdown.log, so any function can be restored:
--   grant execute on function <signature> to authenticated;   (and to anon only if signed-out use is proven)
-- Trigger functions are skipped (they cannot be called through the API and their EXECUTE is not checked at fire time).
create schema if not exists _fn_lockdown;
create table if not exists _fn_lockdown.log (id bigserial primary key, at timestamptz not null default now(), signature text not null, fname text not null, old_acl text[], action text not null, reason text);
create or replace function _fn_lockdown.run(p_names text[], p_apply boolean) returns table(o_name text, o_signature text, o_action text, o_reason text) language plpgsql as $f$
declare r record; keep text;
begin
  for r in
    select p.oid, p.proname, p.oid::regprocedure::text sig, p.proacl, p.prosecdef
      from pg_proc p
     where p.pronamespace = 'public'::regnamespace and p.prokind = 'f' and p.proname = any(p_names)
       and p.prorettype <> 'trigger'::regtype
     order by p.proname, p.oid
  loop
    keep := null;
    if not (has_function_privilege('anon', r.oid, 'execute') or has_function_privilege('authenticated', r.oid, 'execute')) then
      o_name := r.proname; o_signature := r.sig; o_action := 'skip'; o_reason := 'already closed to anon and authenticated'; return next; continue;
    end if;
    select string_agg(distinct d.classid::regclass::text, ',') into keep
      from pg_depend d
     where d.refclassid = 'pg_proc'::regclass and d.refobjid = r.oid and d.deptype in ('n','a')
       and ( d.classid in ('pg_policy'::regclass, 'pg_attrdef'::regclass, 'pg_constraint'::regclass, 'pg_trigger'::regclass)
          or (d.classid = 'pg_class'::regclass)
          or (d.classid = 'pg_rewrite'::regclass and exists (select 1 from pg_rewrite rw join pg_class vc on vc.oid = rw.ev_class where rw.oid = d.objid and coalesce(vc.reloptions::text, '') ilike '%security_invoker=true%'))
          or (d.classid = 'pg_proc'::regclass and exists (select 1 from pg_proc q where q.oid = d.objid and not q.prosecdef)) );
    if keep is not null then o_name := r.proname; o_signature := r.sig; o_action := 'keep'; o_reason := 'dependency: ' || keep; return next; continue; end if;
    if exists (select 1 from pg_proc q where q.pronamespace = 'public'::regnamespace and not q.prosecdef and q.oid <> r.oid and q.prosrc ~ ('\m' || r.proname || '\M')) then
      o_name := r.proname; o_signature := r.sig; o_action := 'keep'; o_reason := 'named in a caller-run function body'; return next; continue;
    end if;
    if exists (select 1 from aclexplode(coalesce(r.proacl, acldefault('f', (select proowner from pg_proc where oid = r.oid)))) a join pg_roles ro on ro.oid = a.grantee where ro.rolname not in ('postgres','anon','authenticated','service_role','supabase_admin')) then
      o_name := r.proname; o_signature := r.sig; o_action := 'keep'; o_reason := 'explicit grant to another role'; return next; continue;
    end if;
    o_name := r.proname; o_signature := r.sig; o_reason := 'no dependency found';
    if p_apply then
      insert into _fn_lockdown.log(signature, fname, old_acl, action, reason) values (r.sig, r.proname, (select array_agg(x::text) from unnest(coalesce(r.proacl, '{}'::aclitem[])) x), 'revoked', o_reason);
      execute format('revoke execute on function %s from public, anon, authenticated', r.sig);
      execute format('grant execute on function %s to service_role', r.sig);
      o_action := 'revoked';
    else
      o_action := 'would-revoke';
    end if;
    return next;
  end loop;
end $f$;

